import se.mickelus.tetra.FeatureFlag;
import se.mickelus.tetra.TetraMod;
import se.mickelus.tetra.TetraToolActions;
import se.mickelus.tetra.Tooltips;
import se.mickelus.tetra.blocks.PropertyMatcher;
import se.mickelus.tetra.blocks.TetraBlock;
import se.mickelus.tetra.blocks.forged.ForgedBlockCommon;
import se.mickelus.tetra.blocks.salvage.BlockInteraction;
import se.mickelus.tetra.blocks.salvage.IInteractiveBlock;
import se.mickelus.tetra.properties.IToolProvider;

import javax.annotation.Nullable;
import javax.annotation.ParametersAreNonnullByDefault;
import java.util.Collection;
import java.util.List;
import java.util.Optional;

@ParametersAreNonnullByDefault
public class ChthonicExtractorBlock extends TetraBlock implements IInteractiveBlock, EntityBlock {
    public static final String identifier = "chthonic_extractor";
    public static final String usedIdentifier = "chthonic_extractor_used";
    public static final String description = "block.tetra.chthonic_extractor.description";
    public static final String extendedDescription = "block.tetra.chthonic_extractor.description_extended";
    public static final int maxDamage = 1024;
    protected static final VoxelShape shape = Shapes.or(
            Block.box(7.0D, 0.0D, 7.0D, 9.0D, 16.0D, 9.0D),
            Block.box(6.0D, 15.0D, 6.0D, 10.0D, 16.0D, 10.0D));
    static final BlockInteraction[] interactions = new BlockInteraction[] {
            new BlockInteraction(TetraToolActions.hammer, 4, Direction.UP, 0, 4, 0, 4,
                    PropertyMatcher.any, (world, pos, blockState, player, hand, hitFace) -> hit(world, pos, player, hand)),
            new BlockInteraction(TetraToolActions.hammer, 5, Direction.UP, 0, 4, 0, 4,
                    PropertyMatcher.any, (world, pos, blockState, player, hand, hitFace) -> hit(world, pos, player, hand)),
            new BlockInteraction(TetraToolActions.hammer, 6, Direction.UP, 0, 4, 0, 4,
                    PropertyMatcher.any, (world, pos, blockState, player, hand, hitFace) -> hit(world, pos, player, hand)),
            new BlockInteraction(TetraToolActions.hammer, 7, Direction.UP, 0, 4, 0, 4,
                    PropertyMatcher.any, (world, pos, blockState, player, hand, hitFace) -> hit(world, pos, player, hand))
    };
    @ObjectHolder(registryName = "block", value = TetraMod.MOD_ID + ":" + identifier)
    public static ChthonicExtractorBlock instance;
    @ObjectHolder(registryName = "item", value = TetraMod.MOD_ID + ":" + identifier)
    public static Item item;
    @ObjectHolder(registryName = "item", value = TetraMod.MOD_ID + ":" + usedIdentifier)
    public static Item usedItem;

    public ChthonicExtractorBlock() {
        super(Block.Properties.of()
                .mapColor(MapColor.COLOR_GRAY)
                .sound(SoundType.NETHERITE_BLOCK)
                .strength(2.5F, 2400.0F));
    }

    private static boolean hit(Level world, BlockPos pos, @Nullable Player playerEntity, InteractionHand hand) {
        if (FeatureFlag.isEnabled(FeatureFlag.bedrockExtraction)) {
            int amount = Optional.ofNullable(playerEntity)
                    .map(player -> player.getItemInHand(hand))
                    .filter(itemStack -> itemStack.getItem() instanceof IToolProvider)
                    .map(itemStack -> ((IToolProvider) itemStack.getItem()).getToolEfficiency(itemStack, TetraToolActions.hammer))
                    .map(Math::round)
                    .orElse(4);

            TileEntityOptional.from(world, pos, ChthonicExtractorTile.class).ifPresent(tile -> tile.damage(amount));
            FracturedBedrockBlock.pierce(world, pos.below(), amount);
            world.playSound(playerEntity, pos, SoundEvents.NETHERITE_BLOCK_HIT, SoundSource.PLAYERS, 0.8f, 0.5f);
            return true;
        }
        return false;
    }

    private static int getTier(Level world, BlockPos pos) {
        return TileEntityOptional.from(world, pos.below(), FracturedBedrockTile.class)
                .map(FracturedBedrockTile::getProjectedTier)
                .orElseGet(() -> FracturedBedrockBlock.canPierce(world, pos.below()) ? 0 : -1);
    }

    public static RegistryObject<BlockItem> registerItems(DeferredRegister<Item> registry) {
        registry.register(usedIdentifier, () -> new BlockItem(instance, new Item.Properties().durability(maxDamage)));
        return registry.register(identifier, () -> new BlockItem(instance, new Item.Properties().stacksTo(64)));
    }

    @Override
    public void appendHoverText(final ItemStack stack, @Nullable final BlockGetter world, final List<Component> tooltip, final TooltipFlag advanced) {
        tooltip.add(Component.translatable(description).withStyle(ChatFormatting.GRAY));
        tooltip.add(Component.literal(" "));

        if (Screen.hasShiftDown()) {
            tooltip.add(Tooltips.expanded);
            tooltip.add(Component.literal(" "));
            tooltip.add(ForgedBlockCommon.locationTooltip);
            tooltip.add(Component.literal(" "));
            tooltip.add(Component.translatable(extendedDescription).withStyle(ChatFormatting.GRAY));
        } else {
            tooltip.add(Tooltips.expand);
        }
    }

    @Override
    public void setPlacedBy(Level world, BlockPos pos, BlockState state, LivingEntity placer, ItemStack stack) {
        TileEntityOptional.from(world, pos, ChthonicExtractorTile.class)
                .ifPresent(tile -> tile.setDamage(stack.getDamageValue()));
    }

    public void playerWillDestroy(Level world, BlockPos pos, BlockState state, Player player) {
        TileEntityOptional.from(world, pos, ChthonicExtractorTile.class)
                .ifPresent(tile -> {
                    ItemStack itemStack = getItemStack(tile);

                    ItemEntity itemEntity = new ItemEntity(world, pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D, itemStack);
                    itemEntity.setDefaultPickUpDelay();
                    world.addFreshEntity(itemEntity);
                });

        super.playerWillDestroy(world, pos, state, player);
    }

    @Override
    public List<ItemStack> getDrops(BlockState blockState, LootParams.Builder lootParams) {
        if (lootParams.getOptionalParameter(LootContextParams.BLOCK_ENTITY) instanceof ChthonicExtractorTile tile) {
            lootParams = lootParams.withDynamicDrop(new ResourceLocation("tetra:cthtonic_drop"),
                    consumer -> consumer.accept(getItemStack(tile)));
        }

        return super.getDrops(blockState, lootParams);
    }

    private ItemStack getItemStack(ChthonicExtractorTile tile) {
        if (tile.getDamage() > 0) {
            ItemStack itemStack = new ItemStack(usedItem);
            itemStack.setDamageValue(tile.getDamage());
            return itemStack;
        }

        return new ItemStack(item);
    }

    @Override
    public VoxelShape getShape(BlockState state, BlockGetter worldIn, BlockPos pos, CollisionContext context) {
        return shape;
    }

    @Override
    public BlockInteraction[] getPotentialInteractions(Level world, BlockPos pos, BlockState blockState, Direction face, Collection<ToolAction> tools) {
        int tier = getTier(world, pos);

        // todo: this could be less hacky
        if (FeatureFlag.isEnabled(FeatureFlag.bedrockExtraction) && tier >= 0 && face == Direction.UP) {
            return new BlockInteraction[] { interactions[Math.min(tier, interactions.length - 1)] };
        }

        return new BlockInteraction[0];
    }

    @Override
    public InteractionResult use(BlockState state, Level world, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
        return BlockInteraction.attemptInteraction(world, state, pos, player, hand, hit);
    }

    @Nullable
    @Override
    public BlockEntity newBlockEntity(BlockPos p_153215_, BlockState p_153216_) {
        return new ChthonicExtractorTile(p_153215_, p_153216_);
    }
}

package se.mickelus.tetra.blocks.forged.chthonic;

import net.minecraft.core.BlockPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.EntityBlock;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityTicker;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraftforge.registries.ObjectHolder;
import se.mickelus.mutil.util.TileEntityOptional;
import se.mickelus.tetra.TetraMod;
import se.mickelus.tetra.blocks.TetraBlock;
import se.mickelus.tetra.blocks.forged.extractor.SeepingBedrockBlock;

import javax.annotation.Nullable;
import javax.annotation.ParametersAreNonnullByDefault;

@ParametersAreNonnullByDefault
public class FracturedBedrockBlock extends TetraBlock implements EntityBlock {
    public static final String identifier = "fractured_bedrock";

    @ObjectHolder(registryName = "block", value = TetraMod.MOD_ID + ":" + identifier)
    public static FracturedBedrockBlock instance;

    public FracturedBedrockBlock() {
        super(BlockBehaviour.Properties.of().strength(-1.0F, 3600000.0F).noLootTable());
    }

    public static boolean canPierce(Level world, BlockPos pos) {
        BlockState blockState = world.getBlockState(pos);
        return Blocks.BEDROCK.equals(blockState.getBlock())
                || (blockState.is(SeepingBedrockBlock.instance) && !SeepingBedrockBlock.isActive(blockState));
    }

    public static void pierce(Level world, BlockPos pos, int amount) {
        FracturedBedrockTile tile = TileEntityOptional.from(world, pos, FracturedBedrockTile.class).orElse(null);

        if (tile == null && canPierce(world, pos)) {
            BlockState blockState = world.getBlockState(pos);
            world.setBlock(pos, instance.defaultBlockState(), 2);
            tile = TileEntityOptional.from(world, pos, FracturedBedrockTile.class).orElse(null);

            if (!world.isClientSide) {
                tile.updateLuck();
            }
        }

        if (tile != null) {
            tile.activate(amount);
        }
    }

    @Nullable
    @Override
    public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return new FracturedBedrockTile(pos, state);
    }

    @Nullable
    @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level, BlockState state, BlockEntityType<T> entityType) {
        return getTicker(entityType, FracturedBedrockTile.type, (lvl, pos, blockState, tile) -> tile.tick(lvl, pos, blockState));
    }
}

package se.mickelus.tetra.blocks.forged.chthonic;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.particles.BlockParticleOption;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.Connection;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.tags.BlockTags;
import net.minecraft.tags.TagKey;
import net.minecraft.util.Mth;
import net.minecraft.util.random.WeightedRandomList;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.biome.MobSpawnSettings;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.EntityBlock;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.loot.LootParams;
import net.minecraft.world.level.storage.loot.LootTable;
import net.minecraft.world.level.storage.loot.parameters.LootContextParamSets;
import net.minecraft.world.level.storage.loot.parameters.LootContextParams;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.Vec3;
import net.minecraft.world.phys.shapes.VoxelShape;
import net.minecraftforge.registries.ObjectHolder;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import se.mickelus.mutil.util.CastOptional;
import se.mickelus.tetra.TetraMod;
import se.mickelus.tetra.blocks.forged.extractor.SeepingBedrockBlock;

import javax.annotation.Nullable;
import javax.annotation.ParametersAreNonnullByDefault;
import java.util.Optional;

@ParametersAreNonnullByDefault
public class FracturedBedrockTile extends BlockEntity {

    public static final TagKey<Block> extractorBreakable = BlockTags.create(new ResourceLocation("tetra", "extractor_breakable"));
    private static final Logger logger = LogManager.getLogger();

    private static final String activityKey = "actv";
    private static final String stepKey = "step";
    private static final String luckKey = "luck";
    private static final ResourceLocation[] lootTables = new ResourceLocation[] {
            new ResourceLocation(TetraMod.MOD_ID, "extractor/tier1"),
            new ResourceLocation(TetraMod.MOD_ID, "extractor/tier2"),
            new ResourceLocation(TetraMod.MOD_ID, "extractor/tier3"),
            new ResourceLocation(TetraMod.MOD_ID, "extractor/tier4")
    };
    @ObjectHolder(registryName = "block_entity_type", value = TetraMod.MOD_ID + ":" + FracturedBedrockBlock.identifier)
    public static BlockEntityType<FracturedBedrockTile> type;
    private final float spawnRatio = 0.5f;
    private final int spawnYLimit = 4;
    private int activity = 0;
    private int step = 0;
    private int luck = 0;
    private MobSpawnSettings spawnInfo;

    public FracturedBedrockTile(BlockPos pos, BlockState blockState) {
        super(type, pos, blockState);
    }

    public static boolean breakBlock(Level world, BlockPos pos, BlockState blockState) {
        if (world instanceof ServerLevel serverLevel
                && !blockState.isAir()
                && blockState.is(extractorBreakable)
                && blockState.getDestroySpeed(world, pos) > -1) {
            BlockEntity tile = blockState.getBlock() instanceof EntityBlock ? world.getBlockEntity(pos) : null;
            LootParams.Builder lootBuilder = new LootParams.Builder(serverLevel)
                    .withParameter(LootContextParams.ORIGIN, Vec3.atCenterOf(pos))
                    .withParameter(LootContextParams.TOOL, ItemStack.EMPTY)
                    .withOptionalParameter(LootContextParams.BLOCK_ENTITY, tile)
                    .withOptionalParameter(LootContextParams.THIS_ENTITY, null);

            blockState.getDrops(lootBuilder).forEach(itemStack -> Block.popResource(world, pos, itemStack));

            world.levelEvent(null, 2001, pos, Block.getId(world.getBlockState(pos)));
            world.setBlock(pos, Blocks.AIR.defaultBlockState(), 2);

            return true;
        }

        return false;
    }

    public void updateLuck() {
        if (spawnInfo == null) {
            spawnInfo = level.getBiome(worldPosition).value().getMobSettings();
        }

        boolean spawnBonus = spawnInfo.getMobs(MobCategory.MONSTER).unwrap().stream()
                .map(spawner -> spawner.type)
                .anyMatch(type -> EntityType.HUSK.equals(type) || EntityType.STRAY.equals(type) || EntityType.WITCH.equals(type));
        if (spawnBonus) {
            luck += 1;
        }
    }

    public void activate(int amount) {
        if (!level.isClientSide && activity <= 0) {
            playSound();
        }

        int preTier = getProjectedTier();

        activity += amount;
        setChanged();

        if (!level.isClientSide && getProjectedTier() != preTier) {
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 3);
        }
    }

    private int getRate() {
        return 20 - Mth.clamp(activity / 64 * 5, 0, 15);
    }

    private int getIntensity() {
        return Math.min(1 + activity / 16, 4);
    }

    public int getProjectedTier() {
        return getTier(step + activity);
    }

    private int getTier() {
        return getTier(step);
    }

    private int getTier(int ref) {
        if (ref > ChthonicExtractorBlock.maxDamage * 10) {
            return 3;
        } else if (ref > ChthonicExtractorBlock.maxDamage * 4) {
            return 2;
        } else if (ref > ChthonicExtractorBlock.maxDamage) {
            return 1;
        }
        return 0;
    }

    private int getMaxDistance() {
        switch (getTier()) {
            case 0:
                return 12;
            case 1:
                return 16;
            case 2:
                return 20;
            case 3:
                return 25;
        }

        return 25;
    }

    private boolean shouldDeplete() {
        return step >= ChthonicExtractorBlock.maxDamage * 12;
    }

    private Vec3 getTarget(int i) {
        int maxDistance = getMaxDistance();
        int steps = 32;
        double directionRotation = 90d * (i % 4);
        double offsetRotation = 360d / steps * (i / 4) + i / 8f;
        float pitch = -(i % (steps * 16)) / steps * 5f;

        return Vec3.directionFromRotation(pitch, (float) (directionRotation + offsetRotation)).multiply(maxDistance, 4 + maxDistance / 2f, maxDistance);
    }

    private boolean isBedrock(Block block) {
        return Blocks.BEDROCK.equals(block)
                || FracturedBedrockBlock.instance.equals(block)
                || SeepingBedrockBlock.instance.equals(block)
                || ChthonicExtractorBlock.instance.equals(block);
    }

    private boolean canReplace(BlockState blockState) {
        return blockState.is(BlockTags.REPLACEABLE);
    }

    // todo 1.18: changed significantly, verify functionality
    private BlockHitResult raytrace(Level level, Vec3 origin, Vec3 target) {
        return BlockGetter.traverseBlocks(origin, target, new ClipContext(origin, target, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, null), (ctx, blockPos) -> {
            BlockState blockState = level.getBlockState(blockPos);
            Block block = blockState.getBlock();

            if (isBedrock(block) || canReplace(blockState)) {
                return null;
            }

            VoxelShape voxelshape = ctx.getBlockShape(blockState, level, blockPos);
            return level.clipWithInteractionOverride(origin, target, blockPos, voxelshape, blockState);
        }, ctx -> {
            Vec3 vec3 = ctx.getFrom().subtract(ctx.getTo());
            return BlockHitResult.miss(ctx.getTo(), Direction.getNearest(vec3.x, vec3.y, vec3.z), BlockPos.containing(ctx.getTo()));
        });
    }

    private BlockPos traceDown(BlockPos blockPos, int minY, Level level) {
        BlockPos.MutableBlockPos movePos = blockPos.mutable();

        while (movePos.getY() > minY) {
            movePos.move(Direction.DOWN);
            BlockState blockState = level.getBlockState(movePos);

            if (isBedrock(blockState.getBlock())) {
                return movePos.move(Direction.UP).immutable();
            }

            if (!blockState.isAir()) {
                return movePos.immutable();
            }
        }

        return movePos.immutable();
    }

    private void spawnOre(BlockPos pos) {
        ServerLevel serverWorld = (ServerLevel) level;
        LootTable table = serverWorld.getServer().getLootData().getLootTable(lootTables[getTier()]);
        LootParams context = new LootParams.Builder(serverWorld).withLuck(luck).create(LootContextParamSets.EMPTY);

        table.getRandomItems(context).stream()
                .filter(itemStack -> !itemStack.isEmpty())
                .findAny()
                .ifPresent(itemStack -> {
                    if (itemStack.getItem() instanceof BlockItem blockItem) {
                        BlockState newState = blockItem.getBlock().defaultBlockState();
                        level.levelEvent(null, 2001, pos, Block.getId(newState));
                        level.setBlock(pos, newState, 2);
                    } else {
                        Block.popResource(level, pos, itemStack);
                    }
                });
    }

    /**
     * Spawns one of the biomes "monster type" mobs at the given location, based on {@link net.minecraft.world.level.NaturalSpawner}
     *
     * @param pos
     */
    private void spawnMob(BlockPos pos) {
        if (spawnInfo == null) {
            spawnInfo = level.getBiome(pos).value().getMobSettings();
        }

        if (getBlockPos().distSqr(pos) < 42 || level.getRandom().nextFloat() >= spawnInfo.getCreatureProbability() / 4) {
            return;
        }

        WeightedRandomList<MobSpawnSettings.SpawnerData> spawners = spawnInfo.getMobs(MobCategory.MONSTER);
        Optional<MobSpawnSettings.SpawnerData> optionalSpawnerData = spawners.getRandom(level.getRandom());
        if (!optionalSpawnerData.isPresent())
            return;
        MobSpawnSettings.SpawnerData mob = optionalSpawnerData.get();
        Vec3 spawnPos = Vec3.atBottomCenterOf(pos);

        ServerLevel serverWorld = (ServerLevel) level;
        if (mob.type.canSummon()
//                && WorldEntitySpawner.canCreatureTypeSpawnAtLocation(EntitySpawnPlacementRegistry.getPlacementType(mob.type), world, pos, mob.type)
                && serverWorld.noCollision(mob.type.getAABB(spawnPos.x, spawnPos.y, spawnPos.z))
                && SpawnPlacements.checkSpawnRules(mob.type, serverWorld, MobSpawnType.SPAWNER, pos, serverWorld.getRandom())) {

            Entity entity;
            try {
                entity = mob.type.create(serverWorld.getLevel());
            } catch (Exception exception) {
                logger.warn("Failed to create mob", exception);
                return;
            }

            entity.moveTo(spawnPos);
            // todo 1.20 verify: hammering an extractor into bedrock spawns mobs (good frequency, correct types, respecting mods)
            CastOptional.cast(entity, Mob.class)
                    .filter(e -> e.checkSpawnRules(serverWorld, MobSpawnType.SPAWNER))
                    .filter(e -> e.checkSpawnObstruction(serverWorld))
                    .ifPresent(e -> {
                        e.finalizeSpawn(serverWorld, serverWorld.getCurrentDifficultyAt(e.blockPosition()), MobSpawnType.SPAWNER, null, null);
                        serverWorld.addFreshEntityWithPassengers(e);

                        // makes the mob angry at a nearby player
                        serverWorld.getEntitiesOfClass(Player.class, new AABB(getBlockPos()).inflate(24, 8, 24)).stream()
                                .findAny()
                                .ifPresent(e::setLastHurtMob);
                    });
        }
    }

    private void playSound() {
        level.playSound(null, worldPosition.below(worldPosition.getY()), SoundEvents.BEACON_AMBIENT, SoundSource.BLOCKS, 3f, 0.5f);
    }

    @Override
    public void load(CompoundTag compound) {
        super.load(compound);

        if (compound.contains(activityKey)) {
            activity = compound.getInt(activityKey);
        }

        if (compound.contains(stepKey)) {
            step = compound.getInt(stepKey);
        }

        if (compound.contains(luckKey)) {
            luck = compound.getInt(luckKey);
        }
    }

    @Override
    public void saveAdditional(CompoundTag compound) {
        super.saveAdditional(compound);

        compound.putInt(activityKey, activity);
        compound.putInt(stepKey, step);
        compound.putInt(luckKey, luck);
    }

    @Nullable
    @Override
    public ClientboundBlockEntityDataPacket getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }

    @Override
    public CompoundTag getUpdateTag() {
        return saveWithoutMetadata();
    }

    @Override
    public void deserializeNBT(CompoundTag nbt) {
        super.deserializeNBT(nbt);
    }

    @Override
    public void onDataPacket(Connection net, ClientboundBlockEntityDataPacket packet) {
        this.load(packet.getTag());
    }

    public void tick(Level level, BlockPos pos, BlockState state) {
        if (!level.isClientSide && activity > 0 && level.getGameTime() % getRate() == 0) {
            int intensity = getIntensity();
            Vec3 origin = Vec3.atCenterOf(pos);

            for (int i = 0; i < intensity; i++) {
                Vec3 target = getTarget(step + i);
                BlockHitResult result = raytrace(level, origin, origin.add(target));

                if (result.getType() != HitResult.Type.MISS) {
                    BlockPos hitPos = result.getBlockPos();
                    BlockState hitState = level.getBlockState(hitPos);

                    breakBlock(level, hitPos, hitState);

                    int minY = level.getMinBuildHeight();
                    BlockPos spawnPos = traceDown(hitPos, minY, level);
                    BlockState spawnState = level.getBlockState(spawnPos);

                    if (canReplace(spawnState)) {
                        if (level.getRandom().nextFloat() < spawnRatio) {
                            if (spawnPos.getY() < minY + spawnYLimit) {
                                spawnOre(spawnPos);
                            }
                        } else {
                            spawnMob(spawnPos);
                        }
                    } else {
                        breakBlock(level, spawnPos, spawnState);
                    }
                }
            }

            ((ServerLevel) level).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, FracturedBedrockBlock.instance.defaultBlockState()),
                    worldPosition.getX() + 0.5, worldPosition.getY() + 1.1, worldPosition.getZ() + 0.5,
                    8, 0, level.random.nextGaussian() * 0.1, 0, 0.1);

            step += intensity;
            activity -= intensity;

            if (shouldDeplete()) {
                level.setBlock(getBlockPos(), DepletedBedrockBlock.instance.defaultBlockState(), 2);
            }
        }

        if (!level.isClientSide && activity > 0 && this.level.getGameTime() % 80 == 0) {
            playSound();
        }
    }
}

package se.mickelus.tetra.blocks.forged.hammer;

