        this(EntityRegistry.FROZEN_HUMANOID.get(), level);
        copyEntityVisualProperties(this, entityToCopy);
        if (!(entityToCopy instanceof Player)) {
            setEntityTypeToCopy(entityToCopy.getType());
        }
